using HRM.Models;
using HRM.Models.Archives;
using HRM.Models.Leadership;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace HRM.Api.Data.EntityConfigurations;

public sealed class LeadershipAppointmentsMapping : IEntityTypeConfiguration<LeadershipAppointmentType>, IEntityTypeConfiguration<LeadershipAppointment>, IEntityTypeConfiguration<LeadershipAppointmentOrganisation>, IEntityTypeConfiguration<LeadershipAuthorityGrant>, IEntityTypeConfiguration<LeadershipAttendancePolicy>, IEntityTypeConfiguration<LeadershipDeviceAccess>, IEntityTypeConfiguration<LeadershipDelegation>, IEntityTypeConfiguration<LeadershipAuditLog>
{
    public void Configure(EntityTypeBuilder<LeadershipAppointmentType> b) { b.ToTable("LM_AppointmentTypes"); b.HasKey(x=>x.LeadershipAppointmentTypeId); b.Property(x=>x.Name).HasMaxLength(120).IsRequired(); b.Property(x=>x.Description).HasMaxLength(500); b.HasIndex(x=>x.Name).IsUnique(); }
    public void Configure(EntityTypeBuilder<LeadershipAppointment> b) { b.ToTable("LM_Appointments"); b.HasKey(x=>x.LeadershipAppointmentId); b.Property(x=>x.PositionTitle).HasMaxLength(200).IsRequired(); b.Property(x=>x.Status).HasMaxLength(30).IsRequired(); b.Property(x=>x.AppointmentReference).HasMaxLength(100); b.Property(x=>x.EffectiveFrom).HasColumnType("date"); b.Property(x=>x.EffectiveTo).HasColumnType("date"); b.HasIndex(x=>new{x.IndividualId,x.Status,x.EffectiveFrom}); b.HasOne<Individual>().WithMany().HasForeignKey(x=>x.IndividualId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.AppointingOrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.AdministrativeOrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict); b.HasOne<LeadershipAppointmentType>().WithMany().HasForeignKey(x=>x.LeadershipAppointmentTypeId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipAppointmentOrganisation> b) { b.ToTable("LM_AppointmentOrganisations"); b.HasKey(x=>x.LeadershipAppointmentOrganisationId); b.Property(x=>x.RelationshipType).HasMaxLength(50).IsRequired(); b.Property(x=>x.EffectiveFrom).HasColumnType("date"); b.Property(x=>x.EffectiveTo).HasColumnType("date"); b.HasIndex(x=>new{x.LeadershipAppointmentId,x.OrganisationId,x.RelationshipType,x.EffectiveFrom}).IsUnique(); b.HasOne<LeadershipAppointment>().WithMany(x=>x.Organisations).HasForeignKey(x=>x.LeadershipAppointmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipAuthorityGrant> b) { b.ToTable("LM_AuthorityGrants"); b.HasKey(x=>x.LeadershipAuthorityGrantId); b.Property(x=>x.PermissionCode).HasMaxLength(120).IsRequired(); b.Property(x=>x.ScopeType).HasMaxLength(40).IsRequired(); b.Property(x=>x.Conditions).HasMaxLength(1000); b.Property(x=>x.ValidFrom).HasColumnType("date"); b.Property(x=>x.ValidTo).HasColumnType("date"); b.HasIndex(x=>new{x.LeadershipAppointmentOrganisationId,x.PermissionCode,x.IsActive,x.ValidFrom}); b.HasOne<LeadershipAppointmentOrganisation>().WithMany(x=>x.AuthorityGrants).HasForeignKey(x=>x.LeadershipAppointmentOrganisationId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipAttendancePolicy> b) { b.ToTable("LM_AttendancePolicies"); b.HasKey(x=>x.LeadershipAttendancePolicyId); b.Property(x=>x.VerificationMode).HasMaxLength(40).IsRequired(); b.Property(x=>x.EffectiveFrom).HasColumnType("date"); b.Property(x=>x.EffectiveTo).HasColumnType("date"); b.HasIndex(x=>new{x.LeadershipAppointmentId,x.EffectiveFrom}); b.HasOne<LeadershipAppointment>().WithMany().HasForeignKey(x=>x.LeadershipAppointmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.ManagingOrganisationId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipDeviceAccess> b) { b.ToTable("LM_DeviceAccesses"); b.HasKey(x=>x.LeadershipDeviceAccessId); b.Property(x=>x.DeviceUserId).HasMaxLength(100).IsRequired(); b.Property(x=>x.ValidFrom).HasColumnType("date"); b.Property(x=>x.ValidTo).HasColumnType("date"); b.HasIndex(x=>new{x.AttendanceDeviceId,x.DeviceUserId,x.ValidFrom}); b.HasOne<LeadershipAppointment>().WithMany().HasForeignKey(x=>x.LeadershipAppointmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AttendanceDevice>().WithMany().HasForeignKey(x=>x.AttendanceDeviceId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipDelegation> b) { b.ToTable("LM_Delegations"); b.HasKey(x=>x.LeadershipDelegationId); b.Property(x=>x.PermissionScope).HasMaxLength(120).IsRequired(); b.Property(x=>x.ValidFrom).HasColumnType("date"); b.Property(x=>x.ValidTo).HasColumnType("date"); b.HasIndex(x=>new{x.ToUserId,x.OrganisationId,x.IsActive,x.ValidFrom}); b.HasOne<LeadershipAppointment>().WithMany().HasForeignKey(x=>x.FromLeadershipAppointmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x=>x.ToUserId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<LeadershipAuditLog> b) { b.ToTable("LM_AuditLogs"); b.HasKey(x=>x.LeadershipAuditLogId); b.Property(x=>x.Action).HasMaxLength(80).IsRequired(); b.Property(x=>x.Detail).HasMaxLength(2000); b.HasIndex(x=>new{x.LeadershipAppointmentId,x.TimestampUtc}); b.HasOne<LeadershipAppointment>().WithMany().HasForeignKey(x=>x.LeadershipAppointmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x=>x.PerformedByUserId).OnDelete(DeleteBehavior.Restrict); }
}
